CREATE TABLE IF NOT EXISTS public.payment_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, payment_id uuid NOT NULL REFERENCES public.payments(id) ON DELETE CASCADE, installment_id uuid REFERENCES public.installments(id) ON DELETE RESTRICT, amount numeric NOT NULL CHECK (amount > 0), created_at timestamptz NOT NULL DEFAULT now());